import numpy as np, json, heapq, math, sys
from PIL import Image
from scipy.ndimage import gaussian_filter, median_filter, binary_closing

def lab(a):
 a=np.asarray(a,dtype=np.float32);a=np.where(a<=.04045,a/12.92,((a+.055)/1.055)**2.4)
 a=a@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]],dtype=np.float32).T
 a=a/np.array([.95047,1,1.08883],dtype=np.float32);a=np.where(a>(6/29)**3,a**(1/3),a/(3*(6/29)**2)+4/29)
 return np.stack([116*a[...,1]-16,500*(a[...,0]-a[...,1]),200*(a[...,1]-a[...,2])],-1)

class Cand:
 def __init__(self,c,r,orient,line,a,b):
  self.c=c;self.r=r;self.orient=orient;self.line=line;self.a=a;self.b=b
  if orient==0: self.bbox=(max(0,line-r),min(255,line+r),max(0,a-r),min(255,b+r))
  else:self.bbox=(max(0,a-r),min(255,b+r),max(0,line-r),min(255,line+r))
  y0,y1,x0,x1=self.bbox
  yy,xx=np.mgrid[y0:y1+1,x0:x1+1]
  if orient==0: dist=(yy-line)**2+(xx-np.clip(xx,a,b))**2
  else: dist=(xx-line)**2+(yy-np.clip(yy,a,b))**2
  self.pix=((yy*256+xx)[dist<=r*r]).astype(np.int32)
  self.score=0.;self.ver=0

def runs(arr):
 edges=np.flatnonzero(np.diff(np.r_[0,arr.astype(np.int8),0]));return list(zip(edges[::2],edges[1::2]))

def build():
 spec=json.load(open('/app/output/spec.json'));p=np.array([w['rgb'] for w in spec['static']['wells']['wells']],dtype=np.float32)
 t=np.asarray(Image.open('/app/target.png')).astype(np.float32)/255
 t=gaussian_filter(t,(4.5,4.5,0))[::4,::4]
 L=lab(t);pl=lab(p)
 d2=((L[None,:,:,:]-pl[:,None,None,:])**2).sum(-1).astype(np.float32)
 label=d2.argmin(0).astype(np.uint8)
 label=median_filter(label,size=(5,5))
 cands=[]
 for c in range(15):
  for r,step,minlen in [(7,8,10),(5,5,7),(3,3,4)]:
   for orient in [0,1]:
    for line in range(1,255,step):
     a=label[line,:] if orient==0 else label[:,line]
     mask=binary_closing(a==c,structure=np.ones(3))
     for lo,hi in runs(mask):
      if hi-lo<minlen:continue
      margin=min(.75*r,(hi-lo-1)/2)
      x0=int(round(lo+margin));x1=int(round(hi-1-margin))
      if x1<x0:x0=x1=int(round((lo+hi-1)/2))
      cands.append(Cand(c,r,orient,line,x0,x1))
 return p,L,d2,label,cands

