 p,L,d2,label,cands=build();print('candidates',len(cands),flush=True)
 d2f=d2.reshape(16,-1);cur=np.full(256*256,15,dtype=np.uint8)
 bins=[[] for _ in range(16*16)]
 for i,v in enumerate(cands):
  y0,y1,x0,x1=v.bbox
  for by in range(y0//16,y1//16+1):
   for bx in range(x0//16,x1//16+1):bins[by*16+bx].append(i)
 def score(v):
