"""RoboPaint episode painter. Run: python gen.py base | paint [count].
The JSON checkpoint and saved trajectories make service reconnects safe without reset.
"""
import os,sys,json,math,time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); Q=np.array([0.,1.,0.,0.]); DT=.05

class Trajectory:
 def __init__(self,start):self.xyz=np.array(start[:3],float);self.rows=[];self.ends=[]
 def line(self,xyz,speed=.12):
  xyz=np.array(xyz,float);d=np.linalg.norm(xyz-self.xyz);n=max(1,math.ceil(d/(speed*DT)))
  for p in np.linspace(self.xyz,xyz,n+1)[1:]:self.rows.append([*p,*Q])
  self.xyz=xyz
 def hold(self,n=5):
  for _ in range(n):self.rows.append([*self.xyz,*Q])
 def mark(self):self.ends.append(len(self.rows))
 def array(self):return np.asarray(self.rows,np.float32)

def well(c):
 if c<=6:col=0;row=c-1
 elif c<=12:col=1;row=c-7
 else:col=2;row=c-12
 return -.155+.0225*row,.135+.0225*col

def pixel_world(v,u):
 mm=.227185/1024
 return .0135925-(v+.5)*mm,.1135925-(u+.5)*mm

def dip(tr,c):
 x,y=well(c)
 tr.line([x,y,.065],.15);tr.hold(4)
 tr.line([x,y,.021],.08);tr.hold(9)
 tr.line([x,y,.060],.10);tr.hold(5)

def build_base(start):
 tr=Trajectory(start);dip(tr,16)
 xs=np.linspace(.0085,-.2085,21)
 ys=[.108,-.108]
 tr.line([xs[0],ys[0],.055],.15);tr.hold(5)
 tr.line([xs[0],ys[0],.010],.07);tr.hold(7)
 for i,x in enumerate(xs):
  dest=ys[(i+1)%2]
  tr.line([x,dest,.010],.06);tr.hold(4)
  if i<len(xs)-1:tr.line([xs[i+1],dest,.010],.05);tr.hold(3)
 tr.mark();tr.line([xs[-1],ys[1],.060],.10);tr.hold(5)
 tr.line([.10,-.20,.11],.15);tr.hold(8)
 return tr

def build_paint(start,strokes,initial_color=16):
 tr=Trajectory(start);loaded=initial_color
 for k,s in enumerate(strokes):
  c=s['c'];r=s['r'];orient=s['o'];line=s['line'];a=s['a'];b=s['b']
  if c!=loaded:dip(tr,c);loaded=c
  if orient==0:v0=v1=(line+.5)*4-.5;u0=(a+.5)*4-.5;u1=(b+.5)*4-.5
  else:u0=u1=(line+.5)*4-.5;v0=(a+.5)*4-.5;v1=(b+.5)*4-.5
  x0,y0=pixel_world(v0,u0);x1,y1=pixel_world(v1,u1)
  z={7:.010,5:.014,3:.017}[r]
  tr.line([x0,y0,.055],.15);tr.hold(4)
  tr.line([x0,y0,z],.07);tr.hold(6)
  tr.line([x1,y1,z],.06);tr.hold(5)
  if r<=5 and (abs(a-b)>1):
   tr.line([x0,y0,z],.06);tr.hold(3)
   tr.line([x1,y1,z],.06);tr.hold(4)
  tr.line([x1,y1,.055],.10);tr.hold(5);tr.mark()
 # Clear the overhead view after every batch.
 tr.line([.10,-.20,.11],.15);tr.hold(8)
 return tr,loaded

def save_json(path,ob):
 tmp=path.with_suffix('.tmp');tmp.write_text(json.dumps(ob,indent=2));os.replace(tmp,path)

def execute(r,name,tr,meta):
 rows_path=OUT/(name+'_rows.npy');state_path=OUT/(name+'_state.json')
 if not state_path.exists():
  np.save(rows_path,tr.array());st={'row':0,'total':len(tr.rows),'start_control_steps':r.status()['control_steps'],'pending':None,'meta':meta,'marks':tr.ends}
  save_json(state_path,st)
 else:st=json.loads(state_path.read_text())
 rows=np.load(rows_path)
 while st['row']<len(rows):
  i=st['row'];n=min(180,len(rows)-i)
  before=r.status();st['pending']={'row':i,'count':n,'calls':before['calls'],'steps':before['control_steps']};save_json(state_path,st)
  try:
   res=r.submit('ee_pose',rows[i:i+n],dt=DT,video='none',cameras=[],note=f'{name} rows {i}-{i+n}')
  except Exception as e:
   print('submit failed',repr(e),flush=True);now=r.wait_ready();print('resumed',now,flush=True)
   if now['calls']>before['calls'] and now['control_steps']>before['control_steps']:
    st['row']=i+n;st['pending']=None;save_json(state_path,st);continue
   st['pending']=None;save_json(state_path,st);continue
  done=int(res.meta.get('executed_rows',n));st['row']=i+done;st['pending']=None;save_json(state_path,st)
  if res.meta.get('n_clipped',0) or any(z.get('ik_failures',0) for z in res.meta.get('plan',[])):
   print('MOTION WARNING',name,i,res.meta.get('n_clipped'),sum(z.get('ik_failures',0) for z in res.meta.get('plan',[])),flush=True)
  if i//180 != (i+n)//180 or st['row']==len(rows):
   print(name,'rows',st['row'],'/',len(rows),'steps',r.status()['control_steps'],'time left',round(res.meta.get('time_left_s',-1)),flush=True)
  if done<n:raise RuntimeError('service stopped early: '+str(res.stopped))
 return st

def main():
 kind=sys.argv[1] if len(sys.argv)>1 else 'paint';r=Robot();state=OUT/'episode_state.json'
 ep=json.loads(state.read_text()) if state.exists() else {'base_done':False,'stroke_done':0,'loaded':1}
 if kind=='base':
  if ep['base_done']:print('base already done');return
  obs=r.get_obs(cameras=[],video='none');tr=build_base(obs.meta['proprio']['now'][7:14]);execute(r,'base',tr,{'kind':'base'})
  ep['base_done']=True;ep['loaded']=16;save_json(state,ep)
 elif kind=='paint':
  if not ep['base_done']:raise RuntimeError('run base first')
  allst=json.loads((OUT/'execution_strokes.json').read_text())
  count=int(sys.argv[2]) if len(sys.argv)>2 else len(allst)-ep['stroke_done']
  st0=ep['stroke_done'];st1=min(len(allst),st0+count)
  if st0>=st1:print('all planned strokes done');return
  name=f'paint_{st0:03d}_{st1:03d}'
  if not (OUT/(name+'_state.json')).exists():
   obs=r.get_obs(cameras=[],video='none');tr,loaded=build_paint(obs.meta['proprio']['now'][7:14],allst[st0:st1],ep['loaded'])
  else:
   tr=Trajectory([0,0,.1]);loaded=allst[st1-1]['c']
  execute(r,name,tr,{'from':st0,'to':st1})
  ep['stroke_done']=st1;ep['loaded']=loaded;save_json(state,ep)
 else:raise ValueError(kind)
 obs=r.get_obs(cameras=['canvas_cam'],video='none');Image.fromarray(obs.last['canvas_cam']).save(OUT/f'after_{kind}_{ep["stroke_done"]:03d}.png')
 print('FINISHED',kind,ep,'status',r.status(),flush=True)
if __name__=='__main__':main()
